cd /dateutil && python - <<'EOF'
from dateutil.relativedelta import relativedelta
from datetime import datetime, date, timedelta
import random, itertools

random.seed(0)
bad = []
for _ in range(20000):
    kw = {}
    for name in ("days","hours","minutes","seconds","microseconds"):
        if random.random() < 0.5:
            kw[name] = random.choice([1,2,-1,-2]) * random.choice([0.5,1.5,2.25,0.1,3.7,10.5])
    if not kw:
        continue
    base = datetime(2003,1,1,12,30,45,123456)
    try:
        got = base + relativedelta(**kw)
    except Exception as e:
        bad.append((kw, "EXC", repr(e)))
        continue
    exp = base + timedelta(**kw)
    if got != exp:
        bad.append((kw, got, exp))
print("mismatches:", len(bad))
for b in bad[:20]:
    print(b)
EOF

